 73→class TRANSLATORSCARD_API UBridgeComponent : public UActorComponent
 74→{
 75→    GENERATED_BODY()
 76→
 77→public:
 78→    UBridgeComponent();
 79→
 80→    virtual void BeginPlay() override;
 81→    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;
