 387→void UBridgeComponent::HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj)
 388→{
 389→    const TSharedPtr<FJsonObject>* FinaleObjPtr;
 390→    const TSharedPtr<FJsonObject>& FinaleData =
 391→        JsonObj->TryGetObjectField(TEXT("finale"), FinaleObjPtr) ? *FinaleObjPtr : JsonObj;
 392→
 393→    FString UsdPath = FinaleData->GetStringField(TEXT("usd_path"));
 394→    FString Message = FinaleData->GetStringField(TEXT("message"));
 395→
 396→    BridgeLog(FString::Printf(TEXT("FINALE: %s"), *Message));
 397→    BridgeLog(FString::Printf(TEXT("USD Path: %s"), *UsdPath));
