 480→void UBridgeComponent::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
 481→{
 482→    FString FilePath = GetBridgeFilePath(Filename);
 483→    FString OutputString;
 484→
 485→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 486→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 487→
 488→    // Write with retry logic (file may be locked by Claude Code reading it)
 489→    int32 MaxRetries = 3;
 490→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 491→    {
 492→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
 493→        {
 494→            return; // Success
 495→        }
 496→
 497→        if (Retry < MaxRetries - 1)
 498→        {
 499→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
 500→            FPlatformProcess::Sleep(0.1f);
 501→        }
 502→    }
 503→
 504→    BridgeLog(FString::Printf(TEXT("ERROR: Failed to write %s after %d retries"), *Filename, MaxRetries));
 505→}
