 529→bool UBridgeComponent::ProcessBridgeStateUsda()
 530→{
 531→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 532→    FString Content;
 533→
 534→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 535→    {
 536→        return false;
 537→    }
 538→
 539→    // Parse sync_status variant
 540→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
 541→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
 542→
 543→    if (bVerboseLogging)
 544→    {
 545→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
 546→    }
 547→
 548→    // Route based on message type
 549→    if (MessageType == TEXT("ready"))
 550→    {
 551→        HandleUsdaReadyState(Content);
 552→    }
 553→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
 554→    {
 555→        HandleUsdaQuestionState(Content);
 556→    }
 557→    else if (MessageType == TEXT("transition"))
 558→    {
 559→        HandleUsdaTransitionState(Content);
 560→    }
 561→    else if (MessageType == TEXT("finale"))
 562→    {
 563→        HandleUsdaFinaleState(Content);
 564→    }
 565→
 566→    return true;
 567→}
