 570→FString UBridgeComponent::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
 571→{
 572→    // Parse variant selection from: variants = { string variantName = "value" }
 573→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 574→    FRegexPattern RegexPattern(Pattern);
 575→    FRegexMatcher Matcher(RegexPattern, Content);
 576→
 577→    if (Matcher.FindNext())
 578→    {
 579→        return Matcher.GetCaptureGroup(1);
 580→    }
 581→    return TEXT("");
 582→}
