 652→void UBridgeComponent::HandleUsdaQuestionState(const FString& Content)
 653→{
 654→    // Parse Message prim
 655→    CurrentQuestion = FTranslatorsQuestion();
 656→    CurrentQuestion.Index = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("index")));
 657→    CurrentQuestion.Total = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("total")));
 658→    CurrentQuestion.QuestionId = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("question_id"));
 659→    CurrentQuestion.Text = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("text"));
 660→    CurrentQuestion.Scene = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("scene"));
 661→
 662→    // Parse Options
 663→    for (int32 i = 0; i < 3; ++i)
 664→    {
 665→        FString OptionPrim = FString::Printf(TEXT("Option_%d"), i);
 666→        FString Label = ParseUsdaAttribute(Content, OptionPrim, TEXT("label"));
 667→        FString Direction = ParseUsdaAttribute(Content, OptionPrim, TEXT("direction"));
 668→
 669→        if (!Label.IsEmpty())
 670→        {
 671→            CurrentQuestion.OptionLabels.Add(Label);
 672→            CurrentQuestion.OptionDirections.Add(Direction);
 673→        }
 674→    }
 675→
 676→    BridgeLog(FString::Printf(TEXT("USD Question %d/%d: %s"),
 677→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.QuestionId));
 678→
 679→    // Build JSON for backward-compatible delegate
 680→    CurrentStateJson = BuildQuestionJson();
 681→    OnQuestionReceived.Broadcast(CurrentStateJson);
 682→}
