  1→/**
  2→ * Profile State — The Translators v5
  3→ *
  4→ * DETERMINISTIC COGNITIVE PROFILE
  5→ *
  6→ * Display profile built from interview answers.
  7→ * Export options: Markdown (with anchor), JSON, USDA (USD format)
  8→ *
  9→ * DETERMINISM: Same answers → Same profile → Same checksum
 10→ * The checksum allows verification of profile integrity.
 11→ */
 12→
 13→import { DIALOGUE } from '../config/index.js';
 14→import { TIMING } from '../config/timing.js';
 15→import { ProfileGenerator } from '../systems/ProfileGenerator.js';
 16→import { USDExporter } from '../systems/USDExporter.js';
 17→import { renderProfile } from '../calibration/index.js';
 18→
 19→export class ProfileState {
 20→  constructor() {
 21→    this.overlay = null;
 22→    this.profile = null;
 23→    this.cognitiveProfile = null;
 24→    this.renderedCognitive = null;
 25→  }
 26→
 27→  enter(game) {
 28→    // Use gameplay-derived profile from calibration
 29→    if (game.calibrationProfile) {
 30→      this.profile = game.calibrationProfile;
 31→    } else {
 32→      // Fallback: Generate from behavior tracker (legacy flow)
 33→      this.profile = ProfileGenerator.generate(
 34→        game.behavior,
 35→        game.directDistance || game.height * 0.63
 36→      );
 37→    }
 38→
 39→    // Extract and render cognitive profile if present
 40→    if (this.profile.cognitive) {
 41→      this.cognitiveProfile = this.profile.cognitive;
 42→      try {
 43→        this.renderedCognitive = renderProfile(this.cognitiveProfile);
 44→      } catch (e) {
 45→        console.warn('Failed to render cognitive profile:', e);
 46→        this.renderedCognitive = null;
 47→      }
 48→    }
 49→
 50→    this.createOverlay(game);
 51→  }
 52→
 53→  exit(game) {
 54→    if (this.overlay) {
 55→      this.overlay.classList.remove('visible');
 56→      setTimeout(() => this.overlay.remove(), 400);
 57→    }
 58→  }
 59→
 60→  createOverlay(game) {
 61→    this.overlay = document.createElement('div');
 62→    this.overlay.className = 'overlay';
 63→
 64→    // Build traits HTML (all content is internally generated, not user input)
 65→    const traitsHTML = this.buildTraitsHTML();
 66→    const insightsHTML = this.buildInsightsHTML();
 67→    const sourcesHTML = this.buildSourcesHTML();
 68→    const cognitiveHTML = this.buildCognitiveHTML();
 69→
 70→    this.overlay.innerHTML = `
 71→      <div class="subtitle">${DIALOGUE.profile.subtitle}</div>
 72→      <div class="title" style="font-size: 1.6rem; margin-top: 8px;">${DIALOGUE.profile.title}</div>
 73→
 74→      <div class="profile-card">
 75→        <div class="profile-section">
 76→          <div class="section-title">${DIALOGUE.profile.patternsHeader}</div>
 77→          <div class="traits-container">${traitsHTML}</div>
 78→        </div>
 79→        <div class="profile-section">
 80→          <div class="section-title">${DIALOGUE.profile.insightsHeader}</div>
 81→          <div class="insights-container">${insightsHTML}</div>
 82→        </div>
 83→        ${cognitiveHTML}
 84→        ${sourcesHTML}
 85→      </div>
 86→
 87→      ${this.buildChecksumHTML()}
 88→
 89→      <button class="btn" id="copyBtn" style="margin-top: 20px;">${DIALOGUE.ui.copyButton}</button>
 90→      <div class="copy-msg" id="copyMsg">${DIALOGUE.ui.copySuccess}</div>
 91→
 92→      <div class="export-options" style="margin-top: 16px; display: flex; gap: 8px; justify-content: center; flex-wrap: wrap;">
 93→        <button class="btn small accent" id="copyAnchorBtn" title="Copy anchor for AI recognition">Copy Anchor</button>
 94→        <button class="btn small" id="downloadMdBtn" title="Download Markdown with anchor">Markdown</button>
 95→        <button class="btn small" id="downloadUsdaBtn" title="Download as USD (Universal Scene Description)">USDA</button>
 96→        <button class="btn small" id="downloadJsonBtn" title="Download as JSON">JSON</button>
 97→      </div>
 98→
 99→      <button class="btn secondary" id="restartBtn" style="margin-top: 16px;">${DIALOGUE.ui.restartButton}</button>
100→    `;
101→
102→    game.ui.appendChild(this.overlay);
103→
104→    // Trigger reflow then add visible class
105→    this.overlay.offsetHeight;
106→    this.overlay.classList.add('visible');
107→
108→    // Bind buttons
109→    this.overlay.querySelector('#copyBtn').onclick = () => this.copyProfile(game);
110→    this.overlay.querySelector('#copyAnchorBtn').onclick = () => this.copyAnchor();
111→    this.overlay.querySelector('#downloadMdBtn').onclick = () => this.downloadMarkdown();
112→    this.overlay.querySelector('#downloadUsdaBtn').onclick = () => this.downloadUSDA();
113→    this.overlay.querySelector('#downloadJsonBtn').onclick = () => this.downloadJSON();
114→    this.overlay.querySelector('#restartBtn').onclick = () => game.restart();
115→  }
116→
117→  buildTraitsHTML() {
118→    const { traits } = this.profile;
119→
120→    // Dynamic trait order based on what dimensions were measured
121→    const allDimensions = [
122→      { key: 'pace', name: 'Pace' },
123→      { key: 'thoroughness', name: 'Detail Preference' },
124→      { key: 'organization', name: 'Structure' },
125→      { key: 'exploration', name: 'Problem Solving' },
126→      { key: 'communication', name: 'Feedback Style' },
127→      { key: 'ambiguity', name: 'Uncertainty' },
128→      { key: 'rhythm', name: 'Conversation Rhythm' },
129→      { key: 'tangents', name: 'Tangents' }
130→    ];
131→
132→    return allDimensions.map(t => {
133→      const trait = traits[t.key];
134→      if (!trait) return '';
135→      return `
136→        <div class="trait">
137→          <span class="trait-name">${t.name}</span>
138→          <span class="trait-value">${trait.label || 'Balanced'}</span>
139→        </div>
140→      `;
141→    }).join('');
142→  }
143→
144→  buildInsightsHTML() {
145→    if (!this.profile.insights || this.profile.insights.length === 0) {
146→      return '<div class="insight">Your communication style adapts to context</div>';
147→    }
148→    return this.profile.insights.map(i => `
149→      <div class="insight">${i}</div>
150→    `).join('');
151→  }
