170→            background: linear-gradient(135deg,
171→              hsl(${hue - 20}, ${saturation}%, ${lightness}%) 0%,
172→              hsl(${hue}, ${saturation}%, ${lightness + 10}%) 50%,
173→              hsl(${hue + 20}, ${saturation}%, ${lightness}%) 100%
