189→  /**
190→   * Build cognitive profile insights display
191→   * Shows empowering insights from deep cognitive profiling
192→   */
193→  buildCognitiveHTML() {
194→    if (!this.renderedCognitive || !this.renderedCognitive.sections.length) {
195→      return '';
196→    }
197→
198→    const { sections, emergentInsights, completeness } = this.renderedCognitive;
199→
200→    let html = `
201→      <div class="profile-section cognitive-section" style="margin-top: 16px; border-top: 1px solid rgba(255,255,255,0.1); padding-top: 16px;">
202→        <div class="section-title" style="font-size: 1rem; color: var(--accent); margin-bottom: 12px;">
203→          Cognitive Insights
204→          <span style="font-size: 0.7rem; color: var(--text-muted); margin-left: 8px;">
205→            ${completeness.percentage}% explored
206→          </span>
207→        </div>
208→    `;
209→
210→    // Render top 3 domain sections (most confident)
211→    const topSections = sections.slice(0, 3);
212→    for (const section of topSections) {
213→      html += `
214→        <div class="cognitive-domain" style="margin-bottom: 16px; padding: 12px; background: rgba(0,0,0,0.2); border-radius: 8px;">
215→          <div style="font-size: 0.85rem; font-weight: 600; color: var(--text);">${section.title}</div>
216→          <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 4px; line-height: 1.4;">
217→            ${this.truncateText(section.description, 150)}
218→          </div>
219→      `;
220→
221→      // Show "explains" bullets
222→      if (section.explains && section.explains.length > 0) {
223→        html += `<div style="margin-top: 8px;">`;
224→        html += `<div style="font-size: 0.7rem; color: var(--accent); margin-bottom: 4px;">This explains:</div>`;
225→        const topExplains = section.explains.slice(0, 2);
226→        for (const explain of topExplains) {
227→          html += `<div style="font-size: 0.7rem; color: var(--text-muted); padding-left: 8px;">• ${explain}</div>`;
228→        }
229→        html += `</div>`;
230→      }
231→
232→      html += `</div>`;
233→    }
234→
235→    // Render emergent patterns (the big insights)
236→    if (emergentInsights && emergentInsights.length > 0) {
237→      html += `
238→        <div class="emergent-patterns" style="margin-top: 12px; padding: 12px; background: linear-gradient(135deg, rgba(92,255,219,0.1), rgba(150,100,255,0.1)); border-radius: 8px; border: 1px solid rgba(92,255,219,0.2);">
239→          <div style="font-size: 0.8rem; font-weight: 600; color: var(--accent); margin-bottom: 8px;">Pattern Recognition</div>
240→      `;
241→
242→      for (const insight of emergentInsights.slice(0, 2)) {
243→        const strength = Math.round(insight.strength * 100);
244→        html += `
245→          <div style="margin-bottom: 8px;">
246→            <div style="font-size: 0.75rem; font-weight: 500; color: var(--text);">
247→              ${insight.title}
248→              <span style="font-size: 0.65rem; color: var(--text-muted);">(${strength}% signal)</span>
249→            </div>
250→            <div style="font-size: 0.7rem; color: var(--text-muted); margin-top: 2px; line-height: 1.4;">
251→              ${this.truncateText(insight.description, 120)}
252→            </div>
253→          </div>
254→        `;
255→      }
256→
257→      html += `</div>`;
258→    }
259→
260→    // Show remaining sections count
261→    if (sections.length > 3) {
262→      html += `
263→        <div style="font-size: 0.7rem; color: var(--text-muted); text-align: center; margin-top: 8px; font-style: italic;">
264→          +${sections.length - 3} more domains explored • Export for full profile
265→        </div>
266→      `;
267→    }
268→
269→    html += `</div>`;
270→    return html;
271→  }
