  1→/**
  2→ * Behavior Tracker — The Translators
  3→ * Source: GAME_SPEC.md "What Gets Measured" sections
  4→ * 
  5→ * Central system for tracking all player behaviors across layers.
  6→ * States should call tracker methods, not modify data directly.
  7→ */
  8→
  9→import { PHYSICS } from '../config/physics.js';
 10→
 11→export class BehaviorTracker {
 12→  constructor() {
 13→    this.reset();
 14→  }
 15→
 16→  /**
 17→   * Reset all tracking data
 18→   */
 19→  reset() {
 20→    // === v2: Character Selection ===
 21→    this.selectedCharacter = null;
 22→    this.characterSelectTime = 0;
 23→    this.characterHoverHistory = [];
 24→
 25→    // === v2: Garden Moments ===
 26→    this.momentData = []; // Array of moment recordings
 27→    this.placements = []; // All object placements
 28→    this.placementSpeeds = [];
 29→    this.momentDurations = [];
 30→    this.revisionCounts = [];
 31→    this.categorySelections = {};
 32→    this.firstChoices = [];
 33→
 34→    // Legacy: Layer 1: Exploration
 35→    this.pathLength = 0;
 36→    this.lastPosition = { x: 0, y: 0 };
 37→    this.orbsCollected = 0;
 38→    this.orbsTotal = 8;
 39→
 40→    // Legacy: Layer 2: Arrangement
 41→    this.arrangeActions = 0;
 42→    this.firstActionTime = null;
 43→    this.layerStartTime = 0;
 44→    this.elementPositions = []; // For analysis
 45→
 46→    // Legacy: Layer 3: Communication
 47→    this.mirrorCount = 0;
 48→    this.interpretCount = 0;
 49→    this.contrastCount = 0;
 50→    this.responseTimes = [];
 51→  }
 52→
 53→  // === v2: Character Selection Methods ===
 54→
 55→  /**
 56→   * Record character selection with timing and hover data
 57→   * @param {string} characterId - Selected character ID
 58→   * @param {number} selectTime - Time to select (ms from start)
 59→   * @param {Array} hoverHistory - Array of hover events
 60→   */
 61→  recordCharacterSelection(characterId, selectTime, hoverHistory) {
 62→    this.selectedCharacter = characterId;
 63→    this.characterSelectTime = selectTime;
 64→    this.characterHoverHistory = hoverHistory;
 65→  }
 66→
 67→  /**
 68→   * Analyze hover behavior for exploration signal
 69→   * Higher exploration = more hovering before deciding
 70→   */
 71→  getCharacterExplorationSignal() {
 72→    if (!this.characterHoverHistory.length) return 0.5;
 73→
 74→    const uniqueHovers = new Set(this.characterHoverHistory.map(h => h.characterId)).size;
 75→    const totalHoverTime = this.characterHoverHistory.reduce((sum, h) => sum + h.duration, 0);
 76→    const hoverCount = this.characterHoverHistory.length;
 77→
 78→    // More unique characters hovered = more exploration
 79→    // More total hover time = more exploration
 80→    // Quick decision = less exploration
 81→
 82→    const explorationScore = Math.min(1, (
 83→      (uniqueHovers / 4) * 0.4 +              // Coverage factor
 84→      Math.min(1, totalHoverTime / 5000) * 0.3 + // Time factor
 85→      Math.min(1, hoverCount / 6) * 0.3        // Revisit factor
 86→    ));
 87→
 88→    return explorationScore;
 89→  }
 90→
 91→  // === v2: Garden Placement Methods ===
 92→
 93→  /**
 94→   * Record an object placement
 95→   * @param {object} data - Placement data
 96→   */
 97→  recordPlacement(data) {
 98→    const { objectId, category, position, momentIndex, timestamp, isFirst } = data;
 99→
100→    this.placements.push({
101→      objectId,
102→      category,
103→      position,
104→      momentIndex,
105→      timestamp
106→    });
107→
108→    // Track category selections
109→    if (!this.categorySelections[category]) {
110→      this.categorySelections[category] = 0;
111→    }
112→    this.categorySelections[category]++;
113→
114→    // Track first choices
115→    if (isFirst) {
116→      this.firstChoices.push({ objectId, category, momentIndex });
117→    }
118→  }
119→
120→  /**
121→   * Record placement speed (time between placements)
122→   * @param {number} speed - Time in ms
123→   */
124→  recordPlacementSpeed(speed) {
125→    this.placementSpeeds.push(speed);
126→  }
127→
128→  /**
129→   * Record moment completion
130→   * @param {object} data - Moment data
131→   */
132→  recordMomentComplete(data) {
133→    const { momentIndex, duration, placementCount, revisions, ambiguityResponse } = data;
134→
135→    this.momentData.push({
136→      momentIndex,
137→      duration,
138→      placementCount,
139→      revisions,
140→      ambiguityResponse
141→    });
142→
143→    this.momentDurations.push(duration);
144→    this.revisionCounts.push(revisions || 0);
145→  }
146→
147→  // === v2: Analysis Methods ===
148→
149→  /**
150→   * Get placement style based on spatial distribution
151→   * @returns {string} 'clustered' | 'spread' | 'structured' | 'organic'
152→   */
153→  getPlacementStyle() {
154→    if (this.placements.length < 3) return 'organic';
155→
156→    const positions = this.placements.map(p => p.position);
157→
158→    // Calculate centroid
159→    const cx = positions.reduce((s, p) => s + p.x, 0) / positions.length;
160→    const cy = positions.reduce((s, p) => s + p.y, 0) / positions.length;
161→
162→    // Calculate spread from centroid
163→    const avgDist = positions.reduce((s, p) => {
164→      return s + Math.sqrt((p.x - cx) ** 2 + (p.y - cy) ** 2);
165→    }, 0) / positions.length;
166→
167→    // Check for alignment (structured)
168→    let alignedH = 0, alignedV = 0;
169→    for (let i = 0; i < positions.length; i++) {
170→      for (let j = i + 1; j < positions.length; j++) {
171→        if (Math.abs(positions[i].y - positions[j].y) < 40) alignedH++;
172→        if (Math.abs(positions[i].x - positions[j].x) < 40) alignedV++;
173→      }
174→    }
175→
176→    const pairCount = (positions.length * (positions.length - 1)) / 2;
177→    const alignmentRatio = (alignedH + alignedV) / (pairCount * 2);
178→
179→    if (alignmentRatio > 0.4) return 'structured';
180→    if (avgDist < 100) return 'clustered';
181→    if (avgDist > 250) return 'spread';
182→    return 'organic';
183→  }
184→
185→  /**
186→   * Get decision speed category
187→   * @returns {string} 'quick' | 'measured' | 'deliberate'
188→   */
189→  getDecisionSpeed() {
190→    if (this.placementSpeeds.length < 2) {
191→      // Fall back to moment durations
192→      if (this.momentDurations.length === 0) return 'measured';
193→      const avgDuration = this.momentDurations.reduce((a, b) => a + b, 0) / this.momentDurations.length;
194→      if (avgDuration < 8000) return 'quick';
195→      if (avgDuration > 20000) return 'deliberate';
196→      return 'measured';
197→    }
198→
199→    const avgSpeed = this.placementSpeeds.reduce((a, b) => a + b, 0) / this.placementSpeeds.length;
200→
201→    if (avgSpeed < 2000) return 'quick';
202→    if (avgSpeed > 5000) return 'deliberate';
203→    return 'measured';
204→  }
205→
206→  /**
207→   * Get iteration style based on revision behavior
208→   * @returns {string} 'iterative' | 'decisive' | 'exploratory'
209→   */
210→  getIterationStyle() {
211→    if (this.revisionCounts.length === 0) return 'decisive';
212→
213→    const avgRevisions = this.revisionCounts.reduce((a, b) => a + b, 0) / this.revisionCounts.length;
214→
215→    if (avgRevisions < 0.5) return 'decisive';
216→    if (avgRevisions > 2) return 'exploratory';
217→    return 'iterative';
218→  }
219→
220→  /**
221→   * Get edge preference (placements near canvas edges)
222→   * @param {number} canvasWidth
223→   * @param {number} canvasHeight
224→   * @returns {number} 0-1 score (higher = more edge preference)
225→   */
226→  getEdgePreference(canvasWidth, canvasHeight) {
227→    if (this.placements.length === 0) return 0.5;
228→
229→    const edgeThreshold = 100;
230→    let edgePlacements = 0;
231→
232→    this.placements.forEach(p => {
233→      if (p.position.x < edgeThreshold ||
234→          p.position.x > canvasWidth - edgeThreshold ||
235→          p.position.y < edgeThreshold ||
236→          p.position.y > canvasHeight - edgeThreshold) {
237→        edgePlacements++;
238→      }
239→    });
240→
241→    return edgePlacements / this.placements.length;
242→  }
243→
244→  // === Layer 1 Methods ===
245→
246→  /**
247→   * Initialize path tracking
248→   */
249→  initPathTracking(x, y) {
250→    this.lastPosition = { x, y };
251→  }
252→
253→  /**
254→   * Track movement for path length calculation
255→   */
256→  trackPath(x, y) {
257→    const dx = x - this.lastPosition.x;
258→    const dy = y - this.lastPosition.y;
259→    this.pathLength += Math.sqrt(dx * dx + dy * dy);
260→    this.lastPosition = { x, y };
261→  }
262→
263→  /**
264→   * Record orb collection
265→   */
266→  collectOrb() {
267→    this.orbsCollected++;
268→  }
269→
270→  /**
271→   * Get exploration score (0-1)
272→   * Higher = more exploration (less direct path)
273→   */
274→  getExplorationScore(directDistance) {
275→    const efficiency = directDistance / Math.max(this.pathLength, directDistance);
276→    return 1 - efficiency;
277→  }
278→
279→  /**
280→   * Get thoroughness score (0-1)
281→   */
282→  getThoroughnessScore() {
283→    return this.orbsCollected / this.orbsTotal;
284→  }
285→
286→  // === Layer 2 Methods ===
287→
288→  /**
289→   * Start arrangement layer timing
290→   */
291→  startArrangeLayer() {
292→    this.layerStartTime = Date.now();
293→  }
294→
295→  /**
296→   * Record an arrange action (drag)
297→   */
298→  recordArrangeAction() {
299→    this.arrangeActions++;
300→    if (this.firstActionTime === null) {
301→      this.firstActionTime = Date.now() - this.layerStartTime;
302→    }
303→  }
304→
305→  /**
306→   * Store final element positions for analysis
307→   */
308→  storeElementPositions(elements) {
309→    this.elementPositions = elements.map(e => ({ x: e.x, y: e.y }));
310→  }
311→
312→  /**
313→   * Analyze organization style
314→   * Source: GAME_SPEC.md "Organization Style Classification"
315→   */
316→  getOrganizationStyle() {
317→    const { analysis } = PHYSICS;
318→    
319→    if (this.arrangeActions < analysis.minimalActionsThreshold) {
320→      return 'minimal';
321→    }
322→    
323→    if (this.elementPositions.length < 2) {
324→      return 'distributed';
325→    }
326→    
327→    // Check for linear alignment
328→    let horizontalAligned = 0;
329→    let verticalAligned = 0;
330→    
331→    for (let i = 0; i < this.elementPositions.length; i++) {
332→      for (let j = i + 1; j < this.elementPositions.length; j++) {
333→        const a = this.elementPositions[i];
334→        const b = this.elementPositions[j];
335→        
336→        if (Math.abs(a.y - b.y) < analysis.alignmentThreshold) {
337→          horizontalAligned++;
338→        }
339→        if (Math.abs(a.x - b.x) < analysis.alignmentThreshold) {
340→          verticalAligned++;
341→        }
342→      }
343→    }
344→    
345→    if (horizontalAligned > analysis.linearAlignmentThreshold || 
346→        verticalAligned > analysis.linearAlignmentThreshold) {
347→      return 'linear';
348→    }
349→    
350→    // Check for clustering
351→    const cx = this.elementPositions.reduce((s, e) => s + e.x, 0) / this.elementPositions.length;
352→    const cy = this.elementPositions.reduce((s, e) => s + e.y, 0) / this.elementPositions.length;
353→    
354→    const clustered = this.elementPositions.filter(e => {
355→      const dist = Math.sqrt((e.x - cx) ** 2 + (e.y - cy) ** 2);
356→      return dist < analysis.clusterThreshold;
357→    }).length;
358→    
359→    if (clustered / this.elementPositions.length > analysis.clusterRatioThreshold) {
360→      return 'clustered';
361→    }
362→    
363→    return 'distributed';
364→  }
365→
366→  // === Layer 3 Methods ===
367→
368→  /**
369→   * Record a signal response
370→   * @param {string} type - 'mirror', 'similar', 'complement', or 'contrast'
371→   * @param {number} responseTime - Time in ms to respond
372→   */
373→  recordSignalResponse(type, responseTime) {
374→    this.responseTimes.push(responseTime);
375→    
376→    if (type === 'mirror') {
377→      this.mirrorCount++;
378→    } else if (type === 'similar' || type === 'complement') {
379→      this.interpretCount++;
380→    } else if (type === 'contrast') {
381→      this.contrastCount++;
382→    }
383→  }
384→
385→  /**
386→   * Get average response time
387→   */
388→  getAverageResponseTime() {
389→    if (this.responseTimes.length === 0) return 3000;
390→    return this.responseTimes.reduce((a, b) => a + b, 0) / this.responseTimes.length;
391→  }
392→
393→  /**
394→   * Get communication style
395→   * Source: GAME_SPEC.md "Communication Style Classification"
396→   */
397→  getCommunicationStyle() {
398→    if (this.mirrorCount >= 2) return 'reflective';
399→    if (this.interpretCount >= 2) return 'interpretive';
400→    if (this.contrastCount >= 2) return 'independent';
401→    return 'adaptive';
402→  }
403→
404→  // === Wolfram Lens Integration ===
405→
406→  /**
407→   * Get signals for Wolfram Lens calibration
408→   * Maps behavioral data to lens parameters
409→   * @param {number} canvasWidth
410→   * @param {number} canvasHeight
411→   * @returns {object} Lens calibration signals (0-1 normalized)
412→   */
413→  getLensSignals(canvasWidth = 800, canvasHeight = 600) {
414→    // Exploration: from character selection + edge preference
415→    const charExploration = this.getCharacterExplorationSignal();
416→    const edgePref = this.getEdgePreference(canvasWidth, canvasHeight);
417→    const exploration = charExploration * 0.6 + edgePref * 0.4;
418→
419→    // Organization: from placement style
420→    const styleToOrg = {
421→      'structured': 0.9,
422→      'clustered': 0.6,
423→      'organic': 0.4,
424→      'spread': 0.3
425→    };
426→    const organization = styleToOrg[this.getPlacementStyle()] || 0.5;
427→
428→    // Thoroughness: from placement count and object coverage
429→    const avgPlacements = this.momentData.length > 0
430→      ? this.momentData.reduce((s, m) => s + m.placementCount, 0) / this.momentData.length
431→      : 2;
432→    const thoroughness = Math.min(1, avgPlacements / 4);
433→
434→    // Pace: from decision speed
435→    const speedToScore = {
436→      'quick': 0.8,
437→      'measured': 0.5,
438→      'deliberate': 0.2
439→    };
440→    const pace = speedToScore[this.getDecisionSpeed()] || 0.5;
441→
442→    // Consistency: from iteration style (decisive = consistent)
443→    const iterToConsist = {
444→      'decisive': 0.8,
445→      'iterative': 0.5,
446→      'exploratory': 0.3
447→    };
448→    const consistency = iterToConsist[this.getIterationStyle()] || 0.5;
449→
450→    // Aesthetic: from category preferences
451→    const categories = this.categorySelections;
452→    const totalSelections = Object.values(categories).reduce((a, b) => a + b, 0) || 1;
453→    const lightPref = (categories['light'] || 0) / totalSelections;
454→    const naturePref = (categories['nature'] || 0) / totalSelections;
455→    // Higher light preference = bold, higher nature = harmonious
456→    const aesthetic = lightPref > 0.4 ? 0.8 : naturePref > 0.4 ? 0.3 : 0.5;
457→
458→    // Intensity: inversely related to moment durations (quick = intense)
459→    const avgDuration = this.momentDurations.length > 0
460→      ? this.momentDurations.reduce((a, b) => a + b, 0) / this.momentDurations.length
461→      : 10000;
462→    const intensity = Math.max(0.2, Math.min(1, 1 - (avgDuration - 5000) / 20000));
463→
464→    // Connection: from revision counts (more revisions = more care = more connection)
465→    const avgRevisions = this.revisionCounts.length > 0
466→      ? this.revisionCounts.reduce((a, b) => a + b, 0) / this.revisionCounts.length
467→      : 0;
468→    const connection = Math.min(1, 0.3 + avgRevisions * 0.2);
469→
470→    // Confidence: based on data quantity
471→    const dataPoints = this.placements.length + this.momentData.length;
472→    const confidence = Math.min(0.95, 0.3 + dataPoints * 0.05);
473→
474→    return {
475→      exploration,
476→      organization,
477→      thoroughness,
478→      pace,
479→      consistency,
480→      aesthetic,
481→      intensity,
482→      connection,
483→      confidence
484→    };
485→  }
486→}
