 30→
 31→export class Game {
 32→  constructor(canvas, uiContainer) {
 33→    // Canvas setup
 34→    this.canvas = canvas;
 35→    this.ctx = canvas.getContext('2d');
 36→    this.ui = uiContainer;
 37→    
 38→    // Dimensions
 39→    this.width = window.innerWidth;
 40→    this.height = window.innerHeight;
 41→    this.resize();
 42→    
 43→    // Systems
 44→    this.renderer = new Renderer(this);
 45→    this.input = new Input(this);
 46→    this.dialogue = new DialogueSystem(this);
 47→    this.behavior = new BehaviorTracker();
 48→    
 49→    // Entities
 50→    this.octopus = new Octopus(this);
 51→    
 52→    // State machine (v3 flow: title → calibration → profile)
 53→    this.states = {
 54→      title: new TitleState(),
 55→      calibration: new CalibrationState(),
 56→      profile: new ProfileState(),
 57→      // Legacy states (kept for reference)
 58→      characterSelect: new CharacterSelectState(),
 59→      garden: new GardenState(),
 60→      layerIntro: new LayerIntroState(),
 61→      explore: new ExploreState(),
 62→      arrange: new ArrangeState(),
 63→      signal: new SignalState()
 64→    };
 65→    this.currentState = null;
 66→    this.currentStateName = '';
 67→
 68→    // v2 game progress
 69→    this.selectedCharacter = null;
 70→    this.currentMoment = 0;
 71→
 72→    // Legacy: Layer progress
 73→    this.currentLayer = 0;
 74→    
 75→    // Time tracking
 76→    this.lastTime = 0;
 77→    this.time = 0;
 78→    
 79→    // Bind methods
 80→    this.loop = this.loop.bind(this);
 81→    this.resize = this.resize.bind(this);
 82→    
 83→    // Event listeners
 84→    window.addEventListener('resize', this.resize);
 85→  }
 86→
 87→  /**
 88→   * Initialize and start the game
 89→   */
 90→  start() {
 91→    this.changeState('title');
 92→    requestAnimationFrame(this.loop);
 93→  }
 94→
 95→  /**
 96→   * Change to a new state
 97→   * @param {string} stateName - Name of state to transition to
 98→   * @param {object} data - Optional data to pass to new state
 99→   */
100→  changeState(stateName, data = {}) {
101→    // Exit current state
102→    if (this.currentState) {
103→      this.currentState.exit(this);
104→    }
105→    
106→    // Enter new state
107→    this.currentStateName = stateName;
108→    this.currentState = this.states[stateName];
109→    
110→    if (!this.currentState) {
111→      console.error(`Unknown state: ${stateName}`);
112→      return;
113→    }
114→    
115→    this.currentState.enter(this, data);
116→  }
117→
118→  /**
119→   * Advance to next layer or profile
120→   */
121→  nextLayer() {
122→    this.currentLayer++;
123→    
124→    if (this.currentLayer < LAYERS.length) {
125→      this.changeState('layerIntro');
126→    } else {
127→      this.changeState('profile');
128→    }
129→  }
130→
131→  /**
132→   * Get current layer config
133→   * @returns {object} Layer configuration
134→   */
135→  getLayerConfig() {
136→    return LAYERS[this.currentLayer];
137→  }
138→
139→  /**
140→   * Restart the game
141→   */
142→  restart() {
143→    // v2 state reset
144→    this.selectedCharacter = null;
145→    this.currentMoment = 0;
146→
147→    // Legacy reset
148→    this.currentLayer = 0;
149→
150→    this.behavior.reset();
151→    this.changeState('title');
152→  }
153→
154→  /**
155→   * Handle window resize
156→   */
157→  resize() {
158→    this.width = window.innerWidth;
159→    this.height = window.innerHeight;
160→    this.canvas.width = this.width;
161→    this.canvas.height = this.height;
162→    
163→    // Notify current state
164→    if (this.currentState && this.currentState.onResize) {
165→      this.currentState.onResize(this);
166→    }
167→  }
168→
169→  /**
170→   * Main game loop
171→   */
172→  loop(timestamp) {
173→    // Calculate delta time
174→    const dt = this.lastTime ? (timestamp - this.lastTime) / 1000 : 0.016;
175→    this.lastTime = timestamp;
176→    this.time += dt;
177→    
178→    // Update
179→    if (this.currentState) {
180→      this.currentState.update(this, dt);
181→    }
