 28→void ATranslatorsHUD::BeginPlay()
 29→{
 30→    Super::BeginPlay();
 31→
 32→    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] BeginPlay - Initializing..."));
 33→
 34→    // Find BridgeComponent
 35→    BridgeComponent = FindBridgeComponent();
 36→
 37→    if (BridgeComponent)
 38→    {
 39→        UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Found BridgeComponent - binding events"));
 40→
 41→        BridgeComponent->OnBridgeReady.AddDynamic(this, &ATranslatorsHUD::OnBridgeReady);
 42→        BridgeComponent->OnQuestionReceived.AddDynamic(this, &ATranslatorsHUD::OnQuestionReceived);
 43→        BridgeComponent->OnTransitionReceived.AddDynamic(this, &ATranslatorsHUD::OnTransitionReceived);
 44→        BridgeComponent->OnFinaleReceived.AddDynamic(this, &ATranslatorsHUD::OnFinaleReceived);
 45→    }
 46→    else
 47→    {
 48→        UE_LOG(LogTemp, Warning, TEXT("[TranslatorsHUD] BridgeComponent not found in level!"));
 49→    }
 50→
 51→    // Create UI widgets
 52→    CreateWidgets();
 53→
 54→    // Show connecting screen initially
 55→    ShowConnectingScreen();
 56→
 57→    // Check if bridge already processed state before we subscribed
 58→    if (BridgeComponent)
 59→    {
 60→        if (BridgeComponent->IsBridgeConnected())
 61→        {
 62→            OnBridgeReady(TotalQuestions);
 63→        }
 64→
 65→        FTranslatorsQuestion Q = BridgeComponent->GetCurrentQuestion();
 66→        if (!Q.QuestionId.IsEmpty())
 67→        {
 68→            UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Catching up - bridge already has question: %s"), *Q.QuestionId);
 69→            CurrentQuestion = Q;
 70→            QuestionStartTime = GetWorld()->GetTimeSeconds();
 71→            if (QuestionWidget)
 72→            {
 73→                QuestionWidget->ShowQuestion(CurrentQuestion);
 74→                QuestionWidget->SetRenderOpacity(1.0f);
 75→            }
 76→            ShowQuestionScreen();
 77→        }
 78→    }
 79→}
 80→
 81→
 82→void ATranslatorsHUD::EndPlay(const EEndPlayReason::Type EndPlayReason)
 83→{
 84→    if (BridgeComponent)
 85→    {
 86→        BridgeComponent->OnBridgeReady.RemoveAll(this);
 87→        BridgeComponent->OnQuestionReceived.RemoveAll(this);
 88→        BridgeComponent->OnTransitionReceived.RemoveAll(this);
 89→        BridgeComponent->OnFinaleReceived.RemoveAll(this);
 90→    }
 91→
 92→    if (QuestionWidget)
 93→    {
 94→        QuestionWidget->OnAnswerSelected.RemoveAll(this);
 95→        QuestionWidget->RemoveFromParent();
 96→    }
 97→    if (ConnectingWidget)
 98→    {
 99→        ConnectingWidget->RemoveFromParent();
100→    }
101→    if (FinaleWidget)
102→    {
103→        FinaleWidget->RemoveFromParent();
104→    }
105→
106→    Super::EndPlay(EndPlayReason);
107→}
