110→UBridgeComponent* ATranslatorsHUD::FindBridgeComponent()
111→{
112→    TArray<AActor*> AllActors;
113→    UGameplayStatics::GetAllActorsOfClass(GetWorld(), AActor::StaticClass(), AllActors);
114→
115→    for (AActor* Actor : AllActors)
116→    {
117→        UBridgeComponent* Bridge = Actor->FindComponentByClass<UBridgeComponent>();
118→        if (Bridge)
119→        {
120→            return Bridge;
121→        }
122→    }
123→
124→    // Fallback: spawn a dedicated actor with BridgeComponent
125→    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] No BridgeComponent found - spawning BridgeActor"));
126→    UWorld* World = GetWorld();
127→    if (World)
128→    {
129→        FActorSpawnParameters SpawnParams;
130→        SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
131→        AActor* BridgeActor = World->SpawnActor<AActor>(AActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
132→        if (BridgeActor)
133→        {
134→            UBridgeComponent* Bridge = NewObject<UBridgeComponent>(BridgeActor, TEXT("BridgeComponent"));
135→            Bridge->bVerboseLogging = true;
136→            BridgeActor->AddInstanceComponent(Bridge);
137→            Bridge->RegisterComponent();
138→            return Bridge;
139→        }
140→    }
141→
142→    return nullptr;
143→}
