447→void ATranslatorsHUD::UpdateTransition(float DeltaSeconds)
448→{
449→    if (TransitionState == EHUDTransition::None)
450→    {
451→        return;
452→    }
453→
454→    TransitionTimer += DeltaSeconds;
455→
456→    switch (TransitionState)
457→    {
458→    case EHUDTransition::AnswerHold:
459→    {
460→        // Hold the selected answer visible for a moment
461→        if (TransitionTimer >= ANSWER_HOLD_TIME)
462→        {
463→            // Now send the answer to bridge
464→            if (BridgeComponent && PendingAnswerIndex >= 0)
465→            {
466→                float ResponseTimeMs = (GetWorld()->GetTimeSeconds() - QuestionStartTime) * 1000.0f;
467→                BridgeComponent->SendAnswer(CurrentQuestion.QuestionId, PendingAnswerIndex, ResponseTimeMs);
468→                UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Sent deferred answer: option %d (%.0fms)"), PendingAnswerIndex, ResponseTimeMs);
469→                PendingAnswerIndex = -1;
470→            }
471→
472→            // Start fade out
473→            TransitionState = EHUDTransition::FadeOut;
474→            TransitionTimer = 0.0f;
475→        }
476→        break;
477→    }
478→
479→    case EHUDTransition::FadeOut:
480→    {
481→        float Alpha = FMath::Clamp(1.0f - (TransitionTimer / FADE_DURATION), 0.0f, 1.0f);
482→        if (QuestionWidget)
483→        {
484→            QuestionWidget->SetRenderOpacity(Alpha);
485→        }
486→
487→        if (TransitionTimer >= FADE_DURATION)
488→        {
489→            // Fully faded out - wait for next question
490→            if (QuestionWidget)
491→            {
492→                QuestionWidget->SetRenderOpacity(0.0f);
493→            }
494→            TransitionState = EHUDTransition::WaitForNext;
495→            TransitionTimer = 0.0f;
496→        }
497→        break;
498→    }
499→
500→    case EHUDTransition::WaitForNext:
501→    {
502→        // Waiting for OnQuestionReceived or OnFinaleReceived to advance us
503→        // Safety timeout: if we wait too long, go back to visible
504→        if (TransitionTimer > 10.0f)
505→        {
506→            UE_LOG(LogTemp, Warning, TEXT("[TranslatorsHUD] Transition timeout - returning to visible"));
507→            if (QuestionWidget)
508→            {
509→                QuestionWidget->SetRenderOpacity(1.0f);
510→            }
511→            TransitionState = EHUDTransition::None;
512→        }
513→        break;
514→    }
515→
516→    case EHUDTransition::FadeIn:
517→    {
518→        float Alpha = FMath::Clamp(TransitionTimer / FADE_DURATION, 0.0f, 1.0f);
519→        if (QuestionWidget)
520→        {
521→            QuestionWidget->SetRenderOpacity(Alpha);
522→        }
523→
524→        if (TransitionTimer >= FADE_DURATION)
525→        {
526→            if (QuestionWidget)
527→            {
528→                QuestionWidget->SetRenderOpacity(1.0f);
529→            }
530→            TransitionState = EHUDTransition::None;
531→            // Reset question start time for input cooldown
532→            QuestionStartTime = GetWorld()->GetTimeSeconds();
533→        }
534→        break;
535→    }
536→
537→    default:
538→        break;
539→    }
540→}
