543→void ATranslatorsHUD::HandleKeyInput()
544→{
545→    // Only accept input when idle (no transition in progress)
546→    if (TransitionState != EHUDTransition::None)
547→    {
548→        return;
549→    }
550→
551→    if (!QuestionWidget || QuestionWidget->GetVisibility() != ESlateVisibility::Visible)
552→    {
553→        return;
554→    }
555→    if (QuestionWidget->GetSelectedOptionIndex() != -1)
556→    {
557→        return;
558→    }
559→
560→    // Guard: ignore input for 0.5s after question appears
561→    float TimeSinceQuestion = GetWorld()->GetTimeSeconds() - QuestionStartTime;
562→    if (TimeSinceQuestion < 0.5f)
563→    {
564→        return;
565→    }
566→
567→    APlayerController* PC = GetOwningPlayerController();
568→    if (!PC)
569→    {
570→        return;
571→    }
572→
573→    if (PC->WasInputKeyJustPressed(EKeys::One) || PC->WasInputKeyJustPressed(EKeys::NumPadOne))
574→    {
575→        OnAnswerSelected(0);
576→    }
577→    else if (PC->WasInputKeyJustPressed(EKeys::Two) || PC->WasInputKeyJustPressed(EKeys::NumPadTwo))
578→    {
579→        OnAnswerSelected(1);
580→    }
581→    else if (PC->WasInputKeyJustPressed(EKeys::Three) || PC->WasInputKeyJustPressed(EKeys::NumPadThree))
582→    {
583→        OnAnswerSelected(2);
584→    }
585→}
