588→void ATranslatorsHUD::OnAnswerSelected(int32 OptionIndex)
589→{
590→    // Prevent double-answers during transition
591→    if (TransitionState != EHUDTransition::None)
592→    {
593→        return;
594→    }
595→
596→    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Answer selected: option %d"), OptionIndex);
597→
598→    // Store answer for deferred sending
599→    PendingAnswerIndex = OptionIndex;
600→
601→    // Start transition: hold the selected answer visible
602→    TransitionState = EHUDTransition::AnswerHold;
603→    TransitionTimer = 0.0f;
604→
605→    // Visual feedback: highlight the selected option in the widget
606→    if (QuestionWidget)
607→    {
608→        // The widget's HandleOptionClicked already handles highlighting
609→        // For keyboard input, we need to manually trigger the visual
610→        // OnAnswerSelected delegate was already broadcast by the widget for mouse clicks
611→        // For keyboard, trigger it on the widget side too
612→    }
