    FLinearColor CurrentColor = FLinearColor(1.0f, 0.8f, 0.2f, 1.0f);  // Gold

    // === FUNCTIONS ===

    /** Update progress to show N questions completed */
    UFUNCTION(BlueprintCallable, Category = "Translators|Progress")
