    FOnBridgeReady OnBridgeReady;

    // === BLUEPRINT CALLABLE FUNCTIONS ===

    /** Send acknowledgment that UE5 is ready */
    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
